static bool Equal(const void* a,const void* b,unsigned int size){const unsigned char* x=(const unsigned char*)a,*y=(const unsigned char*)b;for(unsigned int i=0;i<size;i++)if(x[i]!=y[i])return false;return true;}
static bool InventoryEmpty(const Inventory& b){return !b.rows&&!b.count&&!b.candidates&&!b.noRuntime&&!b.consumedCandidates;}
static bool OrderEmpty(const Order& b){return !b.rows&&!b.count&&!b.sourceObjects&&!b.excludedNoRuntime&&!b.authoredCount&&!b.importedCount;}
static bool Rejected(Inventory& a,Order& b,const NativePreparedRenderScene::Context& scene,unsigned int node=0xffffffffu){return !a.Build(scene)&&InventoryEmpty(a)&&a.error&&a.error[0]&&a.errorNode==node&&!b.Build(scene)&&OrderEmpty(b)&&b.error&&b.error[0]&&b.errorNode==node;}
static bool Four(Inventory& a,Order& b,const NativePreparedRenderScene::Context& scene){return a.Build(scene)&&b.Build(scene)&&a.count==4&&a.candidates==4&&!a.noRuntime&&b.count==4&&b.sourceObjects==4&&!b.excludedNoRuntime;}
static bool Write(HANDLE file,const void* data,unsigned int size){DWORD done=0;return WriteFile(file,data,size,&done,0)&&done==size;}
